import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import app from 'flarum/forum/app';
export default class AnonymousAvatar extends Component {
  view() {
    return m("span", {
      className: `Avatar AnonymousAvatar ${this.attrs.className || ''}`,
      title: app.translator.trans('adminlby-anonymous.forum.anonymous_user', {}, true)
    }, m(Icon, {
      name: "fas fa-user-secret"
    }));
  }
}
flarum.reg.add('adminlby-anonymous', 'forum/components/AnonymousAvatar', AnonymousAvatar);