import app from 'flarum/forum/app';
import { extend, override } from 'flarum/common/extend';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import humanTime from 'flarum/common/helpers/humanTime';
import HeaderListItem from 'flarum/forum/components/HeaderListItem';
import Icon from 'flarum/common/components/Icon';
import Tooltip from 'flarum/common/components/Tooltip';
import username from 'flarum/common/helpers/username';
import punctuateSeries from 'flarum/common/helpers/punctuateSeries';
import humanTimeText from 'flarum/common/utils/humanTime';
import AnonymousAvatar from './components/AnonymousAvatar';
import RevealAuthorModal from './components/RevealAuthorModal';
import ChangeIdentityModal from './components/ChangeIdentityModal';
import installComposer, { quotedReply } from './installComposer';
import installEditHistory from './installEditHistory';
import installCompatibility from './installCompatibility';
export default app.initializers.add('adminlby-anonymous', () => {
  installComposer();
  installEditHistory();
  installCompatibility();
  override('flarum/forum/components/PostUser', 'view', function (original) {
    const post = this.attrs.post;
    if (!post.attribute('isAnonymous')) return original();
    return m("div", {
      className: "PostUser PostUser--anonymous"
    }, m("h3", {
      className: "PostUser-name"
    }, m(AnonymousAvatar, {
      className: "Post-avatar"
    }), m("span", {
      className: "username"
    }, app.translator.trans('adminlby-anonymous.forum.anonymous_user'))), post.attribute('isMine') && app.forum.attribute('anonymousShowOwn') && m("span", {
      className: "AnonymousOwnPost"
    }, app.translator.trans('adminlby-anonymous.forum.own_post')));
  });
  flarum.reg.onLoad('core', 'forum/utils/PostControls', controls => {
    extend(controls, 'moderationControls', function (items, post) {
      if (post.attribute('canChangeAnonymousIdentity')) {
        items.add('anonymousChangeIdentity', m(Button, {
          icon: "fas fa-user-secret",
          onclick: () => app.modal.show(ChangeIdentityModal, {
            post
          })
        }, app.translator.trans(post.attribute('isAnonymous') ? 'adminlby-anonymous.forum.convert_named_button' : 'adminlby-anonymous.forum.convert_anonymous_button')));
      }
      if (post.attribute('isAnonymous') && post.attribute('canRevealAnonymousAuthor')) {
        items.add('anonymousReveal', m(Button, {
          icon: "fas fa-user-shield",
          onclick: () => app.modal.show(RevealAuthorModal, {
            post
          })
        }, app.translator.trans('adminlby-anonymous.forum.reveal_button')));
      }
    });
  });
  override('flarum/forum/components/PostEdited', 'view', function (original) {
    const post = this.attrs.post;
    if (!post.attribute('isAnonymous') && !post.attribute('lastEditIsAnonymous')) return original();
    return m(Tooltip, {
      text: app.translator.trans('adminlby-anonymous.forum.edited_tooltip', {
        ago: humanTimeText(post.editedAt())
      })
    }, m("span", {
      className: "PostEdited"
    }, app.translator.trans('adminlby-anonymous.forum.edited_anonymously')));
  });
  override('flarum/forum/components/EventPost', 'avatar', function (original) {
    return this.attrs.post.attribute('isAnonymous') ? m(AnonymousAvatar, {
      className: "EventPost-icon"
    }) : original();
  });
  override('flarum/forum/components/EventPost', 'content', function (original) {
    const post = this.attrs.post;
    if (!post.attribute('isAnonymous')) return original();
    // Core subclasses override description(), so changing only the base
    // description would leave renamed posts displaying "Deleted user".
    const Post = flarum.reg.checkModule('core', 'forum/components/Post');
    const data = {
      ...this.descriptionData(),
      user: undefined,
      username: m("span", {
        className: "username"
      }, app.translator.trans('adminlby-anonymous.forum.anonymous_user')),
      time: humanTime(post.createdAt())
    };
    return Post.prototype.content.call(this).concat([m("div", {
      className: "EventPost-info"
    }, this.description(data), post.attribute('isMine') && app.forum.attribute('anonymousShowOwn') && m("span", {
      className: "AnonymousOwnPost"
    }, app.translator.trans('adminlby-anonymous.forum.own_post')))]);
  });
  override('flarum/forum/components/PostPreview', 'view', function (original) {
    const post = this.attrs.post;
    if (!post.attribute('isAnonymous')) return original();
    return m(Link, {
      className: "PostPreview",
      href: app.route.post(post),
      onclick: this.attrs.onclick
    }, m("span", {
      className: "PostPreview-content"
    }, m(AnonymousAvatar, null), app.translator.trans('adminlby-anonymous.forum.anonymous_user'), " ", m("span", {
      className: "PostPreview-excerpt"
    }, this.excerpt())));
  });
  override('flarum/forum/components/DiscussionListItem', 'authorItems', function (original) {
    const items = original();
    if (this.attrs.discussion.attribute('isAnonymous')) {
      items.setContent('avatar', m("span", {
        className: "DiscussionListItem-author-avatar"
      }, m(AnonymousAvatar, null)));
    }
    return items;
  });
  override('flarum/forum/components/TerminalPost', 'view', function (original) {
    const discussion = this.attrs.discussion;
    const last = !!this.attrs.lastPost && !!discussion.replyCount();
    if (!discussion.attribute(last ? 'lastPostIsAnonymous' : 'isAnonymous')) return original();
    return m("span", {
      className: "AnonymousTerminalPost"
    }, app.translator.trans(last ? 'adminlby-anonymous.forum.replied' : 'adminlby-anonymous.forum.started', {
      ago: humanTime(discussion[last ? 'lastPostedAt' : 'createdAt']())
    }));
  });
  override('flarum/forum/components/Notification', 'view', function (original) {
    const notification = this.attrs.notification;
    if (!notification.attribute('isAnonymous')) return original();
    const known = ['newPost', 'postMentioned', 'userMentioned', 'groupMentioned', 'discussionRenamed'];
    const type = known.includes(notification.contentType()) ? notification.contentType() : 'generic';
    return m(HeaderListItem, {
      className: `Notification Notification--${notification.contentType()} ${notification.isRead() ? '' : 'unread'}`,
      avatar: m(AnonymousAvatar, null),
      icon: this.icon(),
      content: app.translator.trans(`adminlby-anonymous.forum.notifications.${type}`),
      excerpt: this.excerpt(),
      datetime: notification.createdAt(),
      href: this.href() || '',
      onclick: this.markAsRead.bind(this),
      actions: this.actionItems().toArray()
    });
  });

  // Mentions uses its own name formatter. Never synthesize a User model.
  override('ext:flarum/mentions/forum/mentionables/PostMention', 'replacement', function (original, post) {
    return post.attribute('isAnonymous') ? `@"${app.translator.trans('adminlby-anonymous.forum.anonymous_user', {}, true)}"#p${post.id()}` : original(post);
  });
  override('ext:flarum/mentions/forum/mentionables/PostMention', 'suggestion', function (original, post, typed) {
    return post.attribute('isAnonymous') ? m('[', null, m(AnonymousAvatar, null), app.translator.trans('adminlby-anonymous.forum.anonymous_user'), " ", app.translator.trans('flarum-mentions.forum.composer.reply_to_post_text', {
      number: post.number()
    })) : original(post, typed);
  });

  // Mentions inserts quoted text only after opening the core reply composer.
  // Select the quote identity first, so its independent switch also controls
  // the pre-composer dialog rather than the ordinary-reply switch.
  const reply = (post, quote) => quotedReply(post, quote).catch(error => {
    if (error?.message !== 'anonymous-identity-cancelled') throw error;
  });
  extend('flarum/forum/components/CommentPost', 'actionItems', function (items) {
    if (app.mentionFormats && items.has('reply')) items.get('reply').attrs.onclick = () => reply(this.attrs.post);
  });
  override('ext:flarum/mentions/forum/fragments/PostQuoteButton', 'view', function (original) {
    const view = original();
    view.attrs.onclick = () => reply(this.post, this.content);
    return view;
  });
  extend('flarum/forum/components/CommentPost', 'footerItems', function (items) {
    const post = this.attrs.post;
    const replies = post.mentionedBy?.();
    if (!replies?.some(reply => reply.attribute('isAnonymous')) || !items.has('replies')) return;
    const names = replies.slice(0, 4).map(reply => m(Link, {
      href: app.route.post(reply),
      "data-number": reply.number()
    }, reply.attribute('isAnonymous') ? app.translator.trans('adminlby-anonymous.forum.anonymous_user') : username(reply.user())));
    items.setContent('replies', m("div", {
      className: "Post-mentionedBy"
    }, m("span", {
      className: "Post-mentionedBy-summary"
    }, m(Icon, {
      name: "fas fa-reply"
    }), app.translator.trans('flarum-mentions.forum.post.mentioned_by_text', {
      count: names.length,
      users: punctuateSeries(names)
    }))));
  });
}, -50);