import app from 'flarum/forum/app';
import { override } from 'flarum/common/extend';
import AnonymousAvatar from './components/AnonymousAvatar';
export default function installCompatibility() {
  flarum.reg.onLoad('fof-polls', 'forum/components/ListVotersModal', Modal => {
    override(Modal.prototype, 'voteContent', function (original, vote) {
      return vote.attribute('isAnonymous') ? m("span", {
        className: "AnonymousPollVote"
      }, m(AnonymousAvatar, null), ' ', app.translator.trans('adminlby-anonymous.forum.anonymous_user')) : original(vote);
    });
  });
}